from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)
        if m < n:
            return 0

        suffix0 = [0] * n
        suffix1 = [0] * n

        def can(target: int) -> bool:
            need = (target + points[-1] - 1) // points[-1]
            suffix0[-1] = 0
            suffix1[-1] = max(0, need - 1)

            for i in range(n - 2, -1, -1):
                need = (target + points[i] - 1) // points[i]
                weight = max(0, need - 2)
                suffix0[i] = max(suffix0[i + 1], suffix1[i + 1])
                suffix1[i] = suffix0[i + 1] + weight

            if 2 * n - 1 + 2 * max(suffix0[0], suffix1[0]) <= m:
                return True

            prefix0 = prefix1 = 0

            for end in range(1, n):
                i = end - 1
                need = (target + points[i] - 1) // points[i]
                weight = max(0, need - 1)

                prefix0, prefix1 = max(prefix0, prefix1), prefix0 + weight

                extra = max(
                    prefix0 + max(suffix0[end], suffix1[end]),
                    prefix1 + suffix0[end],
                )

                if 2 * n - end - 1 + 2 * extra <= m:
                    return True

            return False

        low, high = 0, min(points) * m

        while low < high:
            mid = (low + high + 1) // 2
            if can(mid):
                low = mid
            else:
                high = mid - 1

        return low
